def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result") or {}
    outcome = result.get("outcome")
    limit = int(result.get("credit_limit") or 0)

    # Network referral rule (all partners):
    # self_employed applicant with requested_limit > 7000 must go to manual
    # review instead of being issued; a decline stays a decline.
    referral = (app.get("employment") == "self_employed"
                and int(app.get("requested_limit") or 0) > 7000)

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    if outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        if referral:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}

    # Unknown outcome: be safe and route to manual review.
    return {"action": "queue_review", "limit": 0}

